<?php
session_start();if(!isset($_SESSION['userName'])||$_SESSION['userName']!=='admin'){header('Location: alogin.php');exit;}require 'dbconfig.php';$sql="SELECT da.CID,c.Name AS ClinicName,c.Town,da.DID,d.Name AS DoctorName,d.Specialization,da.Day,da.Starttime,da.Endtime FROM doctor_availability da LEFT JOIN clinic c ON c.CID=da.CID LEFT JOIN doctor d ON d.DID=da.DID ORDER BY d.Name,c.Name,da.Day,da.Starttime";$result=$conn->query($sql);$count=$result?$result->num_rows:0;$days=['Monday'=>'Pazartesi','Tuesday'=>'Salı','Wednesday'=>'Çarşamba','Thursday'=>'Perşembe','Friday'=>'Cuma','Saturday'=>'Cumartesi','Sunday'=>'Pazar'];?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doktor Programı | Appointment</title><link rel="stylesheet" href="adminmain.css"><style>.admin-wrap{width:min(1200px,calc(100% - 32px));margin:30px auto 60px}.page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:22px}.page-head h1{margin:5px 0 7px;font-size:32px}.page-head p{margin:0;color:var(--admin-muted)}.table-card{padding:0;overflow:hidden}.table-top{display:flex;justify-content:space-between;align-items:center;padding:19px 20px;border-bottom:1px solid var(--admin-border)}.table-top h2{margin:0;font-size:18px}.count{padding:6px 10px;border-radius:999px;background:#eaf2ff;color:var(--admin-primary);font-size:12px;font-weight:800}.table-wrap{overflow:auto}.data-table{width:100%;border-collapse:collapse;min-width:900px}.data-table th,.data-table td{padding:13px 16px;border-bottom:1px solid var(--admin-border);text-align:left}.data-table th{background:#f8fafc;color:#647084;font-size:10px;text-transform:uppercase;letter-spacing:.05em}.data-table td{font-size:13px}.doctor-name,.clinic-name{font-weight:800}.muted{color:var(--admin-muted)}.time{font-variant-numeric:tabular-nums;font-weight:800;white-space:nowrap}.day{font-weight:750}.empty{padding:45px;text-align:center;color:var(--admin-muted)}@media(max-width:600px){.admin-wrap{width:calc(100% - 20px);margin-top:18px}.page-head{align-items:flex-start;flex-direction:column}.page-head .admin-button{width:100%}.table-wrap{overflow-x:auto}.data-table{min-width:850px}.table-top{padding:16px}}</style></head><body><header class="admin-topbar"><a class="admin-brand" href="mainpage.php"><img src="cal.png" alt="Appointment"><span>Appointment</span></a><nav class="admin-nav"><a href="mainpage.php">Panel</a><a href="showdoctor.php">Doktorlar</a><a class="active" href="showdoctorschedule.php">Programlar</a><a href="showclinic.php">Klinikler</a></nav></header><main class="admin-wrap"><div class="page-head"><div><span class="admin-eyebrow">DOKTOR PROGRAMI</span><h1>Çalışma programları</h1><p>Doktorların klinik, gün ve saat bazındaki uygunluklarını görüntüleyin.</p></div><a class="admin-button" href="adddoctorclinic.php">+ Program Ekle</a></div><section class="admin-card table-card"><div class="table-top"><h2>Program kayıtları</h2><span class="count"><?php echo $count;?> kayıt</span></div><?php if(!$count):?><div class="empty">Henüz doktor çalışma programı bulunmuyor.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Klinik</th><th>Doktor</th><th>Uzmanlık</th><th>Gün</th><th>Saat</th></tr></thead><tbody><?php while($r=$result->fetch_assoc()):?><tr><td><span class="clinic-name"><?php echo htmlspecialchars($r['ClinicName']??'Bilinmiyor');?></span><br><span class="muted"><?php echo htmlspecialchars($r['Town']??'');?></span></td><td class="doctor-name">Dr. <?php echo htmlspecialchars($r['DoctorName']??'Bilinmiyor');?></td><td class="muted"><?php echo htmlspecialchars($r['Specialization']??'-');?></td><td class="day"><?php echo htmlspecialchars($days[$r['Day']]??$r['Day']);?></td><td class="time"><?php echo htmlspecialchars(substr($r['Starttime'],0,5));?> – <?php echo htmlspecialchars(substr($r['Endtime'],0,5));?></td></tr><?php endwhile;?></tbody></table></div><?php endif;?></section></main></body></html>